using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using MyDoc.Models;using System.ComponentModel.DataAnnotations;namespace MyDoc.Pages.Account;public sealed class LoginModel(SignInManager<ApplicationUser> signIn):PageModel{[BindProperty]public InputModel Input{get;set;}=new();[BindProperty(SupportsGet=true)]public string?ReturnUrl{get;set;}public sealed class InputModel{[Required,EmailAddress]public string Email{get;set;}="";[Required,DataType(DataType.Password)]public string Password{get;set;}="";public bool RememberMe{get;set;}}public void OnGet(){}public async Task<IActionResult>OnPostAsync(){if(!ModelState.IsValid)return Page();var result=await signIn.PasswordSignInAsync(Input.Email,Input.Password,Input.RememberMe,false);if(result.Succeeded)return LocalRedirect(ReturnUrl??Url.Page("/Index")!);ModelState.AddModelError(string.Empty,"Invalid email or password.");return Page();}}
